"import { writeFileSync } from 'fs';

const fib = (n: number): number[] => {
  const seq: number[] = [];
  let a = 0, b = 1;
  for (let i = 0; i < n; i++) {
    seq.push(a);
    [a, b] = [b, a + b];
  }
  return seq;
};

const result = fib(10);
console.log('Fibonacci sequence:', result.join(', '));

// Write output to file for demonstration
writeFileSync('output.txt', result.join(', '));
"

